# -*- coding: utf-8 -*-
"""Cau goc cua Floyd Ch.7-10 (Dung/Sai va Self-Test) cho module 11. Khoa doc tu van ban cua sach (PDF tr.449, 496, 561, 627 = trang in 448, 495, 560, 626)
va doi chieu voi noi dung muc tuong ung. Mau 'mu' (mu) trong lop chu PDF bi doc thanh 'm': Ch.8 Self-Test 5, 6, 9 da kiem tren anh trang (micro giay).
Ba cau khoa in mau thuan voi chinh van ban cua sach nen dung dap an DUNG va ghi chu (Ch.9 Self-Test 2, Ch.10 Dung/Sai 7, Ch.10 Self-Test 9); Ch.8 Self-Test 10 bo vi can Hinh 8-36 chua doc.
Moi muc: (so, vi, en, dap an, giai thich vi, giai thich en, muc) cho Dung/Sai; (so, vi, en, [lua chon], dap an, giai thich vi, giai thich en, muc) cho Self-Test.
Lua chon la chuoi (giong nhau o hai ngon ngu) hoac (vi, en)."""
Q = '̅'          # dau gach tren ghep: Q + Q
def qb(s): return s.replace('Qb', 'Q' + Q)

TF7 = [
 (1, 'Một chốt (latch) chỉ có một trạng thái bền.', 'A latch has one stable state.', 'F', 'Chốt là thiết bị lưỡng bền (bistable): có hai trạng thái bền là SET và RESET.', 'A latch is bistable: it has two stable states, SET and RESET.', 1),
 (2, 'Chốt được coi là ở trạng thái RESET khi ngõ ra Q ở mức thấp.', 'A latch is considered to be in the RESET state when the Q output is low.', 'T', 'RESET nghĩa là Q = 0 (Floyd, mục Từ khoá).', 'RESET means Q = 0 (Floyd, Key Terms).', 1),
 (3, 'Chốt D có cổng (gated D latch) không thể dùng để đổi trạng thái.', 'A gated D latch cannot be used to change state.', 'F', 'Khi EN = 1, Q theo D, nên chốt đổi trạng thái được; khi EN = 0 nó giữ nguyên.', 'While EN = 1 the output follows D, so the latch can change state; with EN = 0 it holds.', 1),
 (4, 'Flip-flop và chốt đều là thiết bị lưỡng bền.', 'Flip-flops and latches are both bistable devices.', 'T', 'Cả hai đều có hai trạng thái bền; khác nhau ở cách bắt thời điểm đổi trạng thái.', 'Both have two stable states; they differ in how the change of state is timed.', 1),
 (5, 'Flip-flop D kích bằng sườn đổi trạng thái bất cứ khi nào ngõ vào D thay đổi.', 'An edge-triggered D flip-flop changes state whenever the D input changes.', 'F', 'Nó chỉ đổi ở sườn tích cực của xung clock; D đổi giữa hai sườn không ảnh hưởng.', 'It changes only at the active clock edge; a change of D between edges has no effect.', 1),
 (6, 'Ngõ vào clock là cần thiết cho flip-flop kích bằng sườn.', 'A clock input is necessary for an edge-triggered flip-flop.', 'T', 'Sườn clock là thời điểm duy nhất ngõ ra có thể đổi.', 'The clock edge is the only moment the output may change.', 1),
 (7, 'Khi cả J và K đều ở mức cao, flip-flop J-K kích sườn đổi trạng thái ở mỗi xung clock.', 'When both the J and K inputs are HIGH, an edge-triggered J-K flip-flop changes state on each clock pulse.', 'T', 'J = K = 1 là chế độ lật (toggle).', 'J = K = 1 is the toggle mode.', 1),
 (8, 'Mạch một nhịp (one-shot) còn được gọi là mạch đa hài không ổn định (astable).', 'A one-shot is also known as an astable multivibrator.', 'F', 'One-shot là đa hài đơn ổn (monostable); astable là mạch dao động tự do.', 'A one-shot is a monostable multivibrator; the astable is the free-running oscillator.', 1),
 (9, 'Khi được kích, mạch một nhịp tạo ra một xung đơn.', 'When triggered, a one-shot produces a single pulse.', 'T', 'Độ rộng xung do mạch RC quyết định.', 'The width of the pulse is set by an RC circuit.', 1),
 (10, 'Bộ định thời 555 không thể dùng làm mạch dao động xung.', 'The 555 timer cannot be used as a pulse oscillator.', 'F', 'Cấu hình astable của 555 là một mạch dao động (Floyd 7-6).', 'The astable configuration of the 555 is an oscillator (Floyd 7-6).', 1),
]
ST7 = [
 (1, 'Chốt S-R tác dụng mức CAO được tạo bởi hai cổng nối chéo hồi tiếp:', 'An active HIGH input S-R latch is formed by the cross-coupling of', [('hai cổng NOR', 'two NOR gates'), ('hai cổng NAND', 'two NAND gates'), ('hai cổng OR', 'two OR gates'), ('hai cổng AND', 'two AND gates')], 0,
  'Hai cổng NOR nối chéo cho chốt tác dụng mức cao; hai cổng NAND nối chéo cho chốt tác dụng mức thấp.', 'Two cross-coupled NOR gates give the active-HIGH latch; two cross-coupled NAND gates give the active-LOW latch.', 1),
 (2, 'Phát biểu nào KHÔNG đúng với chốt S-R tác dụng mức THẤP?', 'Which of the following is not true for an active LOW input S-R latch?', [(qb('S = 1, R = 1: Q và Qb giữ nguyên'), qb('S = 1, R = 1: Q and Qb unchanged')), qb('S = 0, R = 1: Q = 1, Qb = 0'), qb('S = 1, R = 0: Q = 1, Qb = 0'), qb('S = 0, R = 0: Q = 1, Qb = 1')], 2,
  'Với NAND chéo, R = 0 làm RESET nên Q = 0 và Q̅ = 1; do đó (c) sai. (d) là trạng thái cấm: cả hai ngõ ra bằng 1.', 'With cross-coupled NANDs R = 0 RESETs the latch, so Q = 0 and Q̅ = 1; hence (c) is false. (d) is the forbidden state: both outputs are 1.', 2),
 (3, 'Với tổ hợp ngõ vào D và EN nào thì chốt D bị RESET?', 'For what combinations of the inputs D and EN will a D latch reset?', [('D = THẤP, EN = THẤP', 'D = LOW, EN = LOW'), ('D = THẤP, EN = CAO', 'D = LOW, EN = HIGH'), ('D = CAO, EN = THẤP', 'D = HIGH, EN = LOW'), ('D = CAO, EN = CAO', 'D = HIGH, EN = HIGH')], 1,
  'Chốt D chỉ cập nhật khi EN = CAO và khi đó Q = D; RESET (Q = 0) cần D = THẤP, EN = CAO.', 'A D latch updates only while EN = HIGH and then Q = D; RESET (Q = 0) needs D = LOW and EN = HIGH.', 1),
 (4, 'Flip-flop đổi trạng thái trong:', 'A flip-flop changes its state during the', [('toàn bộ chu kỳ hoạt động', 'complete operational cycle'), ('sườn xuống của xung clock', 'falling edge of the clock pulse'), ('sườn lên của xung clock', 'rising edge of the clock pulse'), ('cả (b) và (c)', 'both answers (b) and (c)')], 3,
  'Tuỳ loại, flip-flop kích ở sườn lên hoặc sườn xuống; không loại nào đổi trong cả chu kỳ.', 'Depending on the type a flip-flop is triggered by the rising or the falling edge; none changes during the whole cycle.', 1),
 (5, 'Mục đích của ngõ vào clock ở flip-flop là:', 'The purpose of the clock input to a flip-flop is to', [('xoá (clear) thiết bị', 'clear the device'), ('đặt (set) thiết bị', 'set the device'), ('luôn làm ngõ ra đổi trạng thái', 'always cause the output to change states'), ('làm ngõ ra nhận trạng thái phụ thuộc vào các ngõ vào điều khiển (J-K hoặc D)', 'cause the output to assume a state dependent on the controlling (J-K or D) inputs')], 3,
  'Clock chỉ báo thời điểm; trạng thái mới do J-K hoặc D quyết định (có thể không đổi).', 'The clock only says when; the new state is decided by the J-K or D inputs (and may be unchanged).', 1),
 (6, 'Với flip-flop D kích bằng sườn:', 'For an edge-triggered D flip-flop,', [('trạng thái chỉ có thể đổi tại sườn xung clock', 'a change in the state of the flip-flop can occur only at a clock pulse edge'), ('trạng thái mới phụ thuộc vào ngõ vào D', 'the state that the flip-flop goes to depends on the D input'), ('ngõ ra theo ngõ vào ở mỗi xung clock', 'the output follows the input at each clock pulse'), ('tất cả các đáp án trên', 'all of these answers')], 3,
  'Cả ba phát biểu đều đúng: đổi ở sườn, giá trị mới là D, và Q lấy D tại mỗi sườn.', 'All three statements are true: it changes at an edge, the new value is D, and Q takes D at every edge.', 1),
 (7, 'Điểm phân biệt flip-flop J-K với flip-flop D là:', 'A feature that distinguishes the J-K flip-flop from the D flip-flop is the', [('chế độ lật (toggle)', 'toggle condition'), ('ngõ vào preset', 'preset input'), ('kiểu clock', 'type of clock'), ('ngõ vào clear', 'clear input')], 0,
  'J = K = 1 làm J-K lật; flip-flop D không có chế độ lật. Cả hai đều có thể có preset, clear và clock sườn.', 'J = K = 1 makes a J-K toggle; a D flip-flop has no toggle mode. Both may have preset, clear and edge clocks.', 1),
 (8, 'Flip-flop ở trạng thái SET khi:', 'A flip-flop is SET when', [('J = 0, K = 0', 'J = 0, K = 0'), ('J = 0, K = 1', 'J = 0, K = 1'), ('J = 1, K = 0', 'J = 1, K = 0'), ('J = 1, K = 1', 'J = 1, K = 1')], 2,
  'J = 1, K = 0 đặt Q = 1 (SET); J = 0, K = 1 làm RESET; 00 giữ nguyên; 11 lật.', 'J = 1, K = 0 sets Q = 1; J = 0, K = 1 resets; 00 holds; 11 toggles.', 1),
 (9, 'Flip-flop J-K có J = 1, K = 1 và clock 10 kHz. Ngõ ra Q là:', 'A J-K flip-flop with J = 1 and K = 1 has a 10 kHz clock input. The Q output is', [('luôn CAO', 'constantly HIGH'), ('luôn THẤP', 'constantly LOW'), ('sóng vuông 10 kHz', 'a 10 kHz square wave'), ('sóng vuông 5 kHz', 'a 5 kHz square wave')], 3,
  'Lật ở mỗi sườn nên một chu kỳ ra ứng với hai chu kỳ vào: tần số chia đôi, 5 kHz.', 'It toggles on every edge, so one output cycle takes two input cycles: the frequency halves to 5 kHz.', 2),
 (10, 'Mạch một nhịp (one-shot) là một loại:', 'A one-shot is a type of', [('đa hài đơn ổn (monostable)', 'monostable multivibrator'), ('đa hài không ổn định (astable)', 'astable multivibrator'), ('bộ định thời', 'timer'), ('cả (a) và (c)', 'answers (a) and (c)'), ('cả (b) và (c)', 'answers (b) and (c)')], 3,
  'One-shot là đa hài đơn ổn và cũng là một bộ định thời.', 'A one-shot is a monostable multivibrator and also a timer.', 1),
 (11, 'Độ rộng xung ra của one-shot không kích lại phụ thuộc vào:', 'The output pulse width of a nonretriggerable one-shot depends on', [('khoảng cách giữa các xung kích', 'the trigger intervals'), ('điện áp nguồn', 'the supply voltage'), ('một điện trở và một tụ điện', 'a resistor and capacitor'), ('điện áp ngưỡng', 'the threshold voltage')], 2,
  'Với 74121: $t_W=0{,}7\\,R\\,C_{EXT}$.', 'For the 74121: $t_W=0.7\\,R\\,C_{EXT}$.', 1),
 (12, 'Mạch đa hài không ổn định (astable):', 'An astable multivibrator', [('cần xung kích tuần hoàn ở ngõ vào', 'requires a periodic trigger input'), ('không có trạng thái ổn định', 'has no stable state'), ('là mạch dao động', 'is an oscillator'), ('tạo ngõ ra xung tuần hoàn', 'produces a periodic pulse output'), ('cả (a), (b), (c) và (d)', 'answers (a), (b), (c), and (d)'), ('chỉ (b), (c) và (d)', 'answers (b), (c), and (d) only')], 5,
  'Astable tự dao động nên không cần xung kích ngoài; vì thế (a) sai và đáp án đúng là (f).', 'An astable free-runs, so it needs no external trigger; (a) is false and the answer is (f).', 2),
]

TF8 = [
 (1, 'Thanh ghi dịch gồm một dãy các flip-flop.', 'Shift registers consist of an arrangement of flip-flops.', 'T', 'Mỗi tầng là một flip-flop; ngõ ra tầng trước đưa vào tầng sau.', 'Each stage is a flip-flop; the output of one stage feeds the next.', 1),
 (2, 'Thanh ghi dịch không thể dùng để lưu dữ liệu.', 'A shift register cannot be used to store data.', 'F', 'Lưu trữ là một chức năng cơ bản của thanh ghi (Floyd 8-1).', 'Storage is one of the basic functions of a register (Floyd 8-1).', 1),
 (3, 'Thanh ghi dịch nối tiếp nhận từng bit một trên một đường.', 'A serial shift register accepts one bit at a time on a single line.', 'T', 'Đó là định nghĩa của ngõ vào nối tiếp.', 'That is what serial input means.', 1),
 (4, 'Mọi thanh ghi dịch đều được xác định bởi các chuỗi trạng thái quy định.', 'All shift registers are defined by specified sequences.', 'F', 'Chỉ bộ đếm thanh ghi dịch (vòng, Johnson) có chuỗi quy định; thanh ghi thường dịch dữ liệu tuỳ ý.', 'Only shift register counters (ring, Johnson) have specified sequences; an ordinary register shifts arbitrary data.', 1),
 (5, 'Bộ đếm thanh ghi dịch là thanh ghi dịch có ngõ ra nối tiếp nối ngược về ngõ vào nối tiếp.', 'A shift register counter is a shift register with the serial output connected back to the serial input.', 'T', 'Nối thẳng cho bộ đếm vòng, nối qua đảo cho bộ đếm Johnson.', 'Connected directly it is a ring counter, through an inverter a Johnson counter.', 1),
 (6, 'Thanh ghi dịch bốn tầng có thể lưu số đếm lớn nhất là mười lăm.', 'A shift register with four stages can store a maximum count of fifteen.', 'T', '$2^4-1=15$ khi dùng cả bốn bit như số nhị phân.', '$2^4-1=15$ when the four bits are used as a binary number.', 1),
 (7, 'Bộ đếm Johnson là một loại thanh ghi dịch đặc biệt.', 'The Johnson counter is a special type of shift register.', 'T', 'Nó là thanh ghi dịch với ngõ ra đảo nối về ngõ vào.', 'It is a shift register with the inverted output fed back to the input.', 1),
 (8, 'Modulus của bộ đếm Johnson 8 bit là tám.', 'The modulus of an 8-bit Johnson counter is eight.', 'F', 'Bộ đếm Johnson n bit có modulus $2n$ = 16.', 'An n-bit Johnson counter has modulus $2n$ = 16.', 1),
 (9, 'Bộ đếm vòng dùng một flip-flop cho mỗi trạng thái trong chuỗi của nó.', 'A ring counter uses one flip-flop for each state in its sequence.', 'T', 'Bộ đếm vòng modulus N cần N flip-flop (một bit 1 chạy vòng).', 'A ring counter of modulus N needs N flip-flops (one circulating 1).', 1),
 (10, 'Thanh ghi dịch không thể dùng làm thiết bị trễ thời gian.', 'A shift register cannot be used as a time delay device.', 'F', 'Trễ = số bit chia tần số clock (Floyd 8-5).', 'Delay = number of bits divided by the clock frequency (Floyd 8-5).', 1),
]
ST8 = [
 (1, 'Chức năng của một thanh ghi gồm:', 'A register\'s functions include', [('lưu dữ liệu', 'data storage'), ('dịch chuyển dữ liệu', 'data movement'), ('không phải (a) cũng không phải (b)', 'neither (a) nor (b)'), ('cả (a) và (b)', 'both (a) and (b)')], 3, 'Thanh ghi vừa lưu vừa dịch chuyển dữ liệu.', 'A register both stores and moves data.', 1),
 (2, 'Để nhập nối tiếp một byte vào thanh ghi dịch 8 bit cần có:', 'To enter a byte of data serially into an 8-bit shift register, there must be', [('một xung clock', 'one clock pulse'), ('hai xung clock', 'two clock pulses'), ('bốn xung clock', 'four clock pulses'), ('tám xung clock', 'eight clock pulses')], 3, 'Mỗi xung clock nhập một bit nên 8 bit cần 8 xung.', 'Each clock pulse enters one bit, so 8 bits need 8 pulses.', 1),
 (3, 'Để nạp song song một byte vào thanh ghi dịch có nạp đồng bộ cần có:', 'To parallel load a byte of data into a shift register with a synchronous load, there must be', [('một xung clock', 'one clock pulse'), ('một xung clock cho mỗi bit 1 của dữ liệu', 'one clock pulse for each 1 in the data'), ('tám xung clock', 'eight clock pulses'), ('một xung clock cho mỗi bit 0 của dữ liệu', 'one clock pulse for each 0 in the data')], 0, 'Nạp song song đưa mọi bit vào cùng lúc, tại một sườn clock.', 'A parallel load puts every bit in at the same time, on one clock edge.', 1),
 (4, 'Chuỗi bit 10110101 được dịch nối tiếp (bit ngoài cùng bên phải vào trước) vào thanh ghi dịch 8 bit ngõ ra song song có trạng thái đầu 11100100. Sau hai xung clock thanh ghi chứa:', 'The group of bits 10110101 is serially shifted (right-most bit first) into an 8-bit parallel output shift register with an initial state of 11100100. After two clock pulses, the register contains', ['01011110', '10110101', '01111001', '00101101'], 2,
  'Dịch phải, bit vào ở đầu trái: xung 1 vào bit 1 cho 11110010; xung 2 vào bit 0 cho 01111001.', 'Shifting right with the input at the left end: pulse 1 enters a 1 giving 11110010; pulse 2 enters a 0 giving 01111001.', 2),
 (5, 'Với clock 100 kHz, tám bit có thể được nhập nối tiếp vào thanh ghi dịch trong:', 'With a 100 kHz clock frequency, eight bits can be serially entered into a shift register in', ['80 μs', '8 μs', '80 ms', '10 μs'], 0, '8 bit × 10 μs = 80 μs (T = 1/100 kHz = 10 μs).', '8 bits × 10 μs = 80 μs (T = 1/100 kHz = 10 μs).', 2),
 (6, 'Với clock 1 MHz, tám bit có thể được nhập song song vào thanh ghi dịch:', 'With a 1 MHz clock frequency, eight bits can be parallel entered into a shift register', [('trong 8 μs', 'in 8 μs'), ('trong thời gian trễ lan truyền của tám flip-flop', 'in the propagation delay time of eight flip-flops'), ('trong 1 μs', 'in 1 μs'), ('trong thời gian trễ lan truyền của một flip-flop', 'in the propagation delay time of one flip-flop')], 3, 'Nạp song song xảy ra đồng thời ở mọi tầng, nên thời gian chỉ bằng trễ lan truyền của một flip-flop (khoá in).', 'A parallel load happens in all stages at once, so the time is one flip-flop propagation delay (printed key).', 2),
 (7, 'Bộ đếm Johnson modulus 8 cần:', 'A modulus-8 Johnson counter requires', [('tám flip-flop', 'eight flip-flops'), ('bốn flip-flop', 'four flip-flops'), ('năm flip-flop', 'five flip-flops'), ('mười hai flip-flop', 'twelve flip-flops')], 1, 'Modulus $=2n$ nên $n=8/2=4$.', 'Modulus $=2n$, so $n=8/2=4$.', 1),
 (8, 'Bộ đếm vòng modulus 8 cần:', 'A modulus-8 ring counter requires', [('tám flip-flop', 'eight flip-flops'), ('bốn flip-flop', 'four flip-flops'), ('năm flip-flop', 'five flip-flops'), ('mười hai flip-flop', 'twelve flip-flops')], 0, 'Modulus bằng số flip-flop: 8.', 'The modulus equals the number of flip-flops: 8.', 1),
 (9, 'Khi một thanh ghi dịch vào nối tiếp/ra nối tiếp 8 bit dùng làm trễ 24 μs, tần số clock phải là:', 'When an 8-bit serial in/serial out shift register is used for a 24 μs time delay, the clock frequency must be', ['41.67 kHz', '333 kHz', '125 kHz', '8 MHz'], 1, '8 bit / 24 μs = 333 kHz (chu kỳ 3 μs).', '8 bits / 24 μs = 333 kHz (period 3 μs).', 2),
]

TF9 = [
 (1, 'Máy trạng thái là mạch tuần tự có số trạng thái hữu hạn xuất hiện theo thứ tự quy định.', 'A state machine is a sequential circuit having a limited number of states occurring in a prescribed order.', 'T', 'Đó là định nghĩa của Floyd 9-1; bộ đếm là một ví dụ.', 'That is Floyd\'s definition in 9-1; a counter is an example.', 1),
 (2, 'Bộ đếm đồng bộ không thể thực hiện bằng flip-flop J-K.', 'Synchronous counters cannot be realized using J-K flip-flops.', 'F', 'Phần lớn bộ đếm đồng bộ dùng flip-flop J-K (Floyd 9-3).', 'Most synchronous counters use J-K flip-flops (Floyd 9-3).', 1),
 (3, 'Bộ đếm không đồng bộ còn được gọi là bộ đếm gợn sóng (ripple).', 'An asynchronous counter is also known as a ripple counter.', 'T', 'Các flip-flop không chung xung clock nên thay đổi lan truyền như sóng.', 'The flip-flops do not share a clock, so changes ripple through.', 1),
 (4, 'Bộ đếm thập phân (decade) có mười hai trạng thái.', 'A decade counter has twelve states.', 'F', 'Có mười trạng thái, 0 đến 9.', 'It has ten states, 0 to 9.', 1),
 (5, 'Bộ đếm bốn tầng có modulus tối đa là mười sáu.', 'A counter with four stages has a maximum modulus of sixteen.', 'T', '$2^4=16$.', '$2^4=16$.', 1),
 (6, 'Để đạt modulus tối đa 32 cần mười sáu tầng.', 'To achieve a maximum modulus of 32, sixteen stages are required.', 'F', '$2^5=32$ nên chỉ cần năm tầng.', '$2^5=32$, so five stages are enough.', 1),
 (7, 'Nếu trạng thái hiện tại là 1000, trạng thái kế của bộ đếm lên/xuống 4 bit ở chế độ ĐẾM XUỐNG là 0111.', 'If the present state is 1000, the next state of a 4-bit up/down counter in the DOWN mode is 0111.', 'T', '8 − 1 = 7 = 0111.', '8 − 1 = 7 = 0111.', 1),
 (8, 'Hai bộ đếm thập phân mắc tầng chia tần số xung clock cho 10.', 'Two cascaded decade counters divide the clock frequency by 10.', 'F', 'Modulus tổng là 10 × 10 = 100 nên chia cho 100.', 'The overall modulus is 10 × 10 = 100, so they divide by 100.', 1),
 (9, 'Bộ đếm có chuỗi cắt cụt có ít trạng thái hơn số trạng thái tối đa của nó.', 'A counter with a truncated sequence has less than its maximum number of states.', 'T', 'Ví dụ bộ đếm BCD dùng 10 trong 16 trạng thái.', 'For example a BCD counter uses 10 of its 16 states.', 1),
 (10, 'Để đạt modulus 100 cần mười bộ đếm thập phân.', 'To achieve a modulus of 100, ten decade counters are required.', 'F', 'Hai bộ đếm thập phân mắc tầng đã cho $10\\times10=100$.', 'Two cascaded decade counters give $10\\times10=100$.', 1),
]
ST9 = [
 (1, 'Máy trạng thái Moore gồm mạch logic tổ hợp quyết định:', 'A Moore state machine consists of combinational logic circuits that determine', [('chuỗi trạng thái', 'sequences'), ('bộ nhớ', 'memory'), ('cả hai', 'both (a) and (b)'), ('không cái nào', 'neither (a) nor (b)')], 2, 'Theo Floyd 9-1: mạch tổ hợp xác định chuỗi trạng thái, cùng với bộ nhớ (flip-flop) tạo thành máy Moore (khoá in).', 'Floyd 9-1: the combinational logic determines the sequence and together with the memory (flip-flops) forms the Moore machine (printed key).', 2),
 (2, 'Ngõ ra của máy trạng thái Mealy phụ thuộc vào:', 'The output of a Mealy machine depends on its', [('ngõ vào', 'inputs'), ('trạng thái kế', 'next state'), ('trạng thái hiện tại', 'present state'), ('cả (a) và (c)', 'answers (a) and (c)')], 3,
  'Floyd 9-1: ngõ ra Mealy phụ thuộc cả trạng thái hiện tại lẫn ngõ vào. Khoá in là (a) chỉ nêu một nửa; site dùng (d).', 'Floyd 9-1: a Mealy output depends on both the present state and the inputs. The printed key is (a), which names only half; the site uses (d).', 2),
 (3, 'Trễ tích luỹ lớn nhất của bộ đếm không đồng bộ phải:', 'The maximum cumulative delay of an asynchronous counter must be', [('lớn hơn chu kỳ của xung clock', 'more than the period of the clock waveform'), ('nhỏ hơn chu kỳ của xung clock', 'less than the period of the clock waveform'), ('bằng chu kỳ của xung clock', 'equal to the period of the clock waveform'), ('cả (a) và (c)', 'both (a) and (c)')], 1, 'Nếu trễ lớn hơn chu kỳ, xung kế đến trước khi các tầng ổn định và đếm sai.', 'If the delay exceeds the period, the next pulse arrives before the stages settle and the count is wrong.', 2),
 (4, 'Bộ đếm thập phân đếm từ không (0000) đến chín (1001) được gọi là:', 'A decade counter with a count of zero (0000) through nine (1001) is known as', [('bộ đếm ASCII', 'an ASCII counter'), ('bộ đếm nhị phân', 'a binary counter'), ('bộ đếm BCD', 'a BCD counter'), ('bộ đếm thập phân', 'a decimal counter')], 2, 'Mười trạng thái đầu của mã BCD 8421 tạo bộ đếm BCD.', 'The first ten states of the 8421 BCD code make a BCD counter.', 1),
 (5, 'Modulus của một bộ đếm là:', 'The modulus of a counter is', [('số flip-flop', 'the number of flip-flops'), ('số trạng thái thực tế trong chuỗi của nó', 'the actual number of states in its sequence'), ('số lần nó quay vòng mỗi giây', 'the number of times it recycles in a second'), ('số trạng thái tối đa có thể có', 'the maximum possible number of states')], 1, 'Modulus là số trạng thái thực sự của chuỗi (có thể nhỏ hơn tối đa).', 'The modulus is the actual number of states in the sequence (it can be below the maximum).', 1),
 (6, 'Bộ đếm nhị phân 3 bit có modulus tối đa là:', 'A 3-bit binary counter has a maximum modulus of', ['3', '6', '8', '16'], 2, '$2^3=8$.', '$2^3=8$.', 1),
 (7, 'Bộ đếm nhị phân 5 bit có modulus tối đa là:', 'A 5-bit binary counter has a maximum modulus of', ['4', '8', '16', '32'], 3, '$2^5=32$.', '$2^5=32$.', 1),
 (8, 'Bộ đếm modulus 12 phải có:', 'A modulus-12 counter must have', [('12 flip-flop', '12 flip-flops'), ('3 flip-flop', '3 flip-flops'), ('4 flip-flop', '4 flip-flops'), ('xung clock đồng bộ', 'synchronous clocking')], 2, '$2^3=8<12\\le 2^4=16$ nên cần 4 flip-flop (bộ đếm cắt cụt).', '$2^3=8<12\\le 2^4=16$, so 4 flip-flops (a truncated counter).', 2),
 (9, 'Ví dụ nào là bộ đếm có modulus bị cắt cụt?', 'Which one of the following is an example of a counter with a truncated modulus?', [('Modulus 8', 'Modulus 8'), ('Modulus 14', 'Modulus 14'), ('Modulus 16', 'Modulus 16'), ('Modulus 32', 'Modulus 32')], 1, '8, 16, 32 là lũy thừa của 2 (đủ modulus); 14 thì không.', '8, 16 and 32 are powers of 2 (full modulus); 14 is not.', 1),
 (10, 'Bộ đếm gợn sóng 4 bit gồm các flip-flop có trễ từ clock đến Q là 12 ns mỗi cái. Để bộ đếm quay từ 1111 về 0000 cần tổng cộng:', 'A 4-bit ripple counter consists of flip-flops that each have a propagation delay from clock to Q output of 12 ns. For the counter to recycle from 1111 to 0000, it takes a total of', ['12 ns', '24 ns', '48 ns', '36 ns'], 2, 'Cả bốn tầng lần lượt đổi: 4 × 12 ns = 48 ns.', 'All four stages change in turn: 4 × 12 ns = 48 ns.', 2),
 (11, 'Bộ đếm BCD là ví dụ của:', 'A BCD counter is an example of', [('bộ đếm đủ modulus', 'a full-modulus counter'), ('bộ đếm thập phân', 'a decade counter'), ('bộ đếm modulus cắt cụt', 'a truncated-modulus counter'), ('cả (b) và (c)', 'answers (b) and (c)')], 3, 'Nó có 10 trạng thái (thập phân) và ít hơn 16 (cắt cụt).', 'It has 10 states (decade) and fewer than 16 (truncated).', 1),
 (12, 'Trạng thái nào hợp lệ trong bộ đếm BCD 8421?', 'Which of the following is a valid state in an 8421 BCD counter?', ['1010', '1011', '1111', '1000'], 3, '1000 = 8; 1010, 1011 và 1111 vượt quá 9.', '1000 = 8; 1010, 1011 and 1111 exceed 9.', 1),
 (13, 'Ba bộ đếm modulus 10 mắc tầng có modulus tổng:', 'Three cascaded modulus-10 counters have an overall modulus of', ['30', '100', '1000', '10,000'], 2, '$10^3=1000$.', '$10^3=1000$.', 1),
 (14, 'Clock 10 MHz đưa vào chuỗi bộ đếm gồm một modulus 5, một modulus 8 và hai modulus 10. Tần số ra thấp nhất có thể là:', 'A 10 MHz clock frequency is applied to a cascaded counter consisting of a modulus-5 counter, a modulus-8 counter, and two modulus-10 counters. The lowest output frequency possible is', ['10 kHz', '2.5 kHz', '5 kHz', '25 kHz'], 1, '$5\\times8\\times10\\times10=4000$; $10\\text{ MHz}/4000=2{,}5$ kHz.', '$5\\times8\\times10\\times10=4000$; $10\\text{ MHz}/4000=2.5$ kHz.', 2),
 (15, 'Bộ đếm lên/xuống nhị phân 4 bit đang ở trạng thái 0000. Trạng thái kế ở chế độ ĐẾM XUỐNG là:', 'A 4-bit binary up/down counter is in the binary state of zero. The next state in the DOWN mode is', ['0001', '1111', '1000', '1110'], 1, 'Đếm xuống từ 0 quay vòng về giá trị lớn nhất, 15 = 1111.', 'Counting down from 0 wraps to the maximum value, 15 = 1111.', 2),
 (16, 'Trạng thái đầu của bộ đếm nhị phân modulus 13 là:', 'The initial count of a modulus-13 binary counter is', ['0000', '1111', '1101', '1100'], 0, 'Bộ đếm modulus 13 đếm từ 0000 đến 1100 (12) rồi quay về 0000.', 'A modulus-13 counter counts from 0000 to 1100 (12) and returns to 0000.', 2),
]

TF10 = [
 (1, 'PAL gồm một mảng cổng OR lập trình được nối với một mảng cổng AND cố định.', 'A PAL consists of a programmable array of OR gates connected to a fixed array of AND gates.', 'F', 'Ngược lại: PAL có mảng AND lập trình được và mảng OR cố định.', 'The other way round: a PAL has a programmable AND array and a fixed OR array.', 1),
 (2, 'SPLD là viết tắt của thiết bị logic khả trình đơn giản.', 'SPLD stands for simple programmable logic device.', 'T', 'Simple Programmable Logic Device.', 'Simple Programmable Logic Device.', 1),
 (3, 'Điển hình, một macrocell gồm một cổng AND và mạch ngõ ra đi kèm.', 'Typically, a macrocell consists of an AND gate and its associated output logic.', 'F', 'Macrocell gồm mảng AND-OR, bộ dồn kênh và flip-flop, không chỉ một cổng AND.', 'A macrocell has an AND-OR array, multiplexers and a flip-flop, not a single AND gate.', 2),
 (4, 'CPLD là viết tắt của thiết bị logic khả trình phức tạp.', 'CPLD stands for complex programmable logic device.', 'T', 'Complex Programmable Logic Device.', 'Complex Programmable Logic Device.', 1),
 (5, 'FPGA là mảng cổng khả trình tại chỗ (sách in nhầm là "FGPA").', 'An FGPA is a field programmable gate array.', 'T', 'Field-Programmable Gate Array; sách in nhầm thứ tự chữ cái nhưng ý đúng.', 'Field-Programmable Gate Array; the book misprints the letters but the meaning is right.', 1),
 (6, 'FPGA điển hình có mật độ cổng lớn hơn CPLD.', 'A typical FPGA has a greater gate density than a CPLD.', 'T', 'FPGA chứa nhiều logic hơn (hàng chục nghìn đến hàng triệu cổng).', 'An FPGA holds much more logic than a CPLD.', 1),
 (7, 'Khối mảng logic (LAB) có trong CPLD.', 'Logic array blocks are found in CPLDs.', 'T', 'Floyd 10-2: mỗi mảng SPLD trong CPLD gọi là LAB. Khoá in là F; site dùng T theo văn bản.', 'Floyd 10-2: each SPLD array in a CPLD is called a LAB. The printed key is F; the site uses T, following the text.', 2),
 (8, 'Quá trình lập trình một PLD được gọi là luồng thiết kế (design flow).', 'The process of programming a PLD is known as design flow.', 'T', 'Luồng thiết kế gồm nhập thiết kế, tổng hợp, mô phỏng và nạp (Floyd 10-5).', 'The design flow covers entry, synthesis, simulation and download (Floyd 10-5).', 1),
 (9, 'Thiết bị đang được lập trình gọi là thiết bị đích (target device).', 'The device being programmed is called a target device.', 'T', 'Target device là chip nhận tệp cấu hình.', 'The target device is the chip that receives the configuration file.', 1),
 (10, 'Hai kiểu nhập thiết kế cho thiết bị khả trình là sơ đồ nguyên lý và HDL.', 'Two types of programmable design entry are schematic and HDL.', 'T', 'Có thể vẽ sơ đồ hoặc viết mã mô tả phần cứng (VHDL, Verilog).', 'You may draw a schematic or write a hardware description language (VHDL, Verilog).', 1),
]
ST10 = [
 (1, 'Hai loại SPLD là:', 'Two types of SPLDs are', [('CPLD và PAL', 'CPLD and PAL'), ('PAL và FPGA', 'PAL and FPGA'), ('PAL và GAL', 'PAL and GAL'), ('GAL và SRAM', 'GAL and SRAM')], 2, 'SPLD gồm PAL và GAL (và PLA); CPLD và FPGA phức tạp hơn.', 'SPLDs are PALs and GALs (and PLAs); CPLDs and FPGAs are more complex.', 1),
 (2, 'PAL là một thiết bị logic:', 'A PAL is a logic device which is', [('lập trình một lần', 'one-time programmable'), ('xoá và lập trình lại được', 'an erasable programmable'), ('xoá và lập trình lại bằng điện', 'electronically erasable and programmable'), ('cả (a) và (b)', 'both (a) and (b)')], 0, 'PAL dùng cầu chì nên chỉ lập trình một lần (GAL mới xoá được).', 'A PAL uses fuses so it is programmed once (a GAL is the erasable one).', 1),
 (3, 'Yếu tố quyết định một GAL có đủ cho thiết kế logic hay không là:', 'The factor that determines the adequacy of a GAL for a logic design is', [('số ngõ vào và ngõ ra', 'the number of inputs and outputs'), ('số cổng tương đương (mật độ)', 'the number of equivalent gates or density'), ('số cổng đảo', 'the number of inverters involved'), ('cả (a) và (b)', 'both (a) and (b)')], 3, 'Cần đủ chân vào/ra và đủ mật độ cổng.', 'You need enough inputs/outputs and enough gate density.', 2),
 (4, 'Macrocell là một phần của:', 'A macrocell is part of a', [('PAL', 'PAL'), ('GAL', 'GAL'), ('CPLD', 'CPLD'), ('cả (a), (b) và (c)', 'answers (a), (b), and (c)')], 3, 'Khoá in (d).', 'Printed key (d).', 2),
 (5, 'LUT trong kiến trúc LUT-CPLD về cơ bản là một bộ nhớ có thể lập trình bằng:', 'The LUT, used in the LUT-CPLD architecture, is basically a memory that can be programmed using', [('hàm POS', 'POS functions'), ('hàm SOP', 'SOP functions'), ('tích các bù', 'product of complements'), ('cả (a), (b) và (c)', 'answers (a), (b), and (c)')], 1, 'Mỗi ô nhớ lưu giá trị của một số hạng tích (Floyd Hình 10-16).', 'Each memory cell stores the value of one product term (Floyd Figure 10-16).', 2),
 (6, 'Thuật ngữ LAB là viết tắt của:', 'The term LAB stands for', [('logic AND block', 'logic AND block'), ('logic array block', 'logic array block'), ('last asserted bit', 'last asserted bit'), ('logic assembly block', 'logic assembly block')], 1, 'Logic array block, mỗi LAB xấp xỉ một SPLD.', 'Logic array block; one LAB is roughly one SPLD.', 1),
 (7, 'Hai chế độ hoạt động của macrocell là:', 'Two modes of macrocell operation are', [('vào và ra', 'input and output'), ('có thanh ghi và tuần tự', 'registered and sequential'), ('tổ hợp và có thanh ghi', 'combinational and registered'), ('song song và dùng chung', 'parallel and shared')], 2, 'Floyd 10-3: chế độ tổ hợp (bỏ qua flip-flop) và chế độ có thanh ghi (ngõ ra qua flip-flop).', 'Floyd 10-3: combinational mode (flip-flop bypassed) and registered mode (output through the flip-flop).', 2),
 (8, 'Flip-flop dùng trong macrocell của CPLD có thể lập trình thành:', 'The flip-flop used in a CPLD macrocell can be programmed as a', [('flip-flop D', 'D flip-flop'), ('flip-flop J-K', 'J-K flip-flop'), ('cả (a) và (b)', 'both (a) and (b)'), ('không loại nào', 'neither (a) nor (b)')], 2, 'Có thể cấu hình D hoặc J-K.', 'It can be configured as D or J-K.', 1),
 (9, 'Một macrocell điển hình gồm:', 'A typical macrocell consists of', [('các cổng, bộ dồn kênh và một flip-flop', 'gates, multiplexers, and a flip-flop'), ('các cổng và một thanh ghi dịch', 'gates and a shift register'), ('một bộ đếm mã Gray', 'a Gray code counter'), ('một mảng logic cố định', 'a fixed logic array')], 0, 'Floyd 10-2: mảng AND-OR, bộ dồn kênh chọn chế độ và flip-flop. Khoá in là (b); site dùng (a) theo văn bản.', 'Floyd 10-2: AND-OR array, mode multiplexers and a flip-flop. The printed key is (b); the site uses (a), following the text.', 2),
 (10, 'Các phần tử cơ bản của FPGA là:', 'The basic elements of an FPGA are', [('khối logic cấu hình được (CLB)', 'configurable logic blocks'), ('khối I/O', 'I/O blocks'), ('mảng PAL', 'PAL arrays'), ('cả (a) và (b)', 'both (a) and (b)')], 3, 'FPGA gồm CLB, khối I/O và đường nối lập trình được.', 'An FPGA has CLBs, I/O blocks and programmable interconnect.', 1),
 (11, 'FPGA không bay hơi (nonvolatile) thường dựa trên công nghệ:', 'Nonvolatile FPGAs are generally based on', [('cầu chì (fuse)', 'fuse technology'), ('antifuse', 'antifuse technology'), ('EEPROM', 'EEPROM technology'), ('SRAM', 'SRAM technology')], 1, 'Theo khoá in và Floyd 10-4: antifuse không mất cấu hình khi tắt nguồn; SRAM thì mất.', 'Printed key and Floyd 10-4: an antifuse keeps its configuration without power; SRAM loses it.', 2),
 (12, 'Khi các khối logic cấu hình được trong FPGA tương đối đơn giản, kiến trúc FPGA là:', 'When the configurable logic blocks in an FPGA are relatively simple, the FPGA architecture is', [('hạt mịn (fine grained)', 'fine grained'), ('hạt thô (coarse grained)', 'coarse grained'), ('lõi cứng (hard core)', 'hard core'), ('lõi mềm (soft core)', 'soft core')], 0, 'Khối đơn giản, nhiều khối: hạt mịn.', 'Simple blocks, many of them: fine grained.', 2),
 (13, 'Môđun logic trong khối logic của FPGA có thể cấu hình cho:', 'The logic module in an FPGA logic block can be configured for', [('logic tổ hợp', 'combinational logic'), ('logic chế độ song song', 'parallel mode logic'), ('logic có thanh ghi', 'registered logic'), ('cả (a) và (c)', 'both (a) and (c)')], 3, 'Môđun cấu hình thành tổ hợp hoặc có thanh ghi.', 'A module is configured as combinational or registered.', 2),
 (14, 'Một môđun logic có thể lập trình cho các chế độ:', 'A logic module can be programmed for the following modes of operations:', [('chế độ thường (normal)', 'normal mode'), ('chế độ số học và số học dùng chung', 'arithmetic and shared arithmetic mode'), ('chế độ LUT mở rộng', 'extended LUT mode'), ('cả (a), (b) và (c)', 'answers (a), (b), and (c)')], 3, 'Cả ba chế độ đều có.', 'All three modes exist.', 2),
 (15, 'Trong mô phỏng chức năng (functional simulation), người dùng phải chỉ định:', 'In a functional simulation, the user must specify the', [('thiết bị đích cụ thể', 'specific target device'), ('dạng sóng ngõ ra', 'output waveform'), ('dạng sóng ngõ vào', 'input waveforms'), ('HDL', 'HDL')], 2, 'Người dùng đặt ngõ vào; công cụ tính ngõ ra. Mô phỏng chức năng chưa cần thiết bị đích.', 'The user supplies the inputs; the tool computes the outputs. A functional simulation needs no target device yet.', 2),
 (16, 'Kết quả cuối cùng của giai đoạn tổng hợp (synthesis) trong luồng thiết kế là:', 'The final output of the synthesis phase of a design flow is the', [('netlist', 'netlist'), ('bitstream', 'bitstream'), ('mô phỏng thời gian', 'timing simulation'), ('số chân của thiết bị', 'device pin numbers')], 0, 'Tổng hợp biến mô tả thành netlist; bitstream đến sau khi xếp và đi dây.', 'Synthesis turns the description into a netlist; the bitstream comes after place and route.', 2),
 (17, 'EDIF là viết tắt của:', 'EDIF stands for', [('electronic device interchange format', 'electronic device interchange format'), ('electrical design integrated fixture', 'electrical design integrated fixture'), ('electrically destructive input function', 'electrically destructive input function'), ('electronic design interchange format', 'electronic design interchange format')], 3, 'Electronic Design Interchange Format.', 'Electronic Design Interchange Format.', 1),
 (18, 'TAP trong quét biên (boundary scan) là viết tắt của:', 'The boundary scan TAP stands for', [('test access point', 'test access point'), ('test array port', 'test array port'), ('test access port', 'test access port'), ('terminal access path', 'terminal access path')], 2, 'Test Access Port.', 'Test Access Port.', 1),
 (19, 'Một ô quét biên điển hình chứa:', 'A typical boundary scan cell contains', [('chỉ flip-flop', 'flip-flops only'), ('flip-flop và logic dồn kênh', 'flip-flops and multiplexer logic'), ('chốt và flip-flop', 'latches and flip-flops'), ('chốt và bộ mã hoá', 'latches and an encoder')], 1, 'Gồm flip-flop và bộ dồn kênh.', 'It has flip-flops and multiplexer logic.', 2),
 (20, 'Chuẩn JTAG có các ngõ vào và ngõ ra:', 'The JTAG standard has the following inputs and outputs', [('Intest, extest, TDI, TDO', 'Intest, extest, TDI, TDO'), ('TDI, TDO, TCK, TMS', 'TDI, TDO, TCK, TMS'), ('ENT, CLK, SHF, CLR', 'ENT, CLK, SHF, CLR'), ('TCK, TMS, TMO, TLF', 'TCK, TMS, TMO, TLF')], 1, 'TDI (dữ liệu vào), TDO (dữ liệu ra), TCK (clock), TMS (chọn chế độ).', 'TDI (data in), TDO (data out), TCK (clock), TMS (mode select).', 2),
 (21, 'BSDL là viết tắt của:', 'The acronym BSDL stands for', [('board standard digital logic', 'board standard digital logic'), ('boundary scan down load', 'boundary scan down load'), ('bistable digital latch', 'bistable digital latch'), ('boundary scan description language', 'boundary scan description language')], 3, 'Boundary Scan Description Language.', 'Boundary Scan Description Language.', 1),
]
